#[no_mangle]
pub unsafe extern "C" fn ones_and_zeros(v:*const i64,n:usize)->i64{if v.is_null()||n<3{return -1}let count=*v;if !(0..=32).contains(&count){return -1}let m=*v.add(1);let ones=*v.add(2);if !(0..=32).contains(&m)||!(0..=32).contains(&ones)||n!=3+2*count as usize{return -1}let mut dp=[[0i64;33];33];for i in 0..count as usize{let z=*v.add(3+2*i);let o=*v.add(4+2*i);if !(0..=32).contains(&z)||!(0..=32).contains(&o){return -1}for a in (z..=m).rev(){for b in (o..=ones).rev(){let candidate=dp[a as usize-z as usize][b as usize-o as usize]+1;if candidate>dp[a as usize][b as usize]{dp[a as usize][b as usize]=candidate}}}}dp[m as usize][ones as usize]}
